const icons={play:'<path d="m9 5 12 9-12 9Z" fill="currentColor" stroke="none"/>',pause:'<path d="M10 6v16M19 6v16" stroke-width="5"/>',back:'<path d="M7 8a10 10 0 1 1-3 9M3 4v7h7"/><text x="9" y="19" stroke="none" fill="currentColor" font-size="10">10</text>',forward:'<path d="M21 8a10 10 0 1 0 3 9M25 4v7h-7"/><text x="9" y="19" stroke="none" fill="currentColor" font-size="10">10</text>',volume:'<path d="M4 11h5l6-5v16l-6-5H4ZM19 9q6 5 0 10M22 5q10 9 0 18"/>',mute:'<path d="M4 11h5l6-5v16l-6-5H4ZM20 10l7 8m0-8-7 8"/>',light:'<circle cx="14" cy="14" r="5"/><path d="M14 1v4m0 18v4M1 14h4m18 0h4M5 5l3 3m12 12 3 3M5 23l3-3M20 8l3-3"/>',expand:'<path d="M4 11V4h7m6 0h7v7M4 17v7h7m6 0h7v-7"/>',lock:'<rect x="5" y="12" width="18" height="13" rx="3"/><path d="M9 12V7a5 5 0 0 1 10 0v5"/>',captions:'<rect x="2" y="5" width="24" height="18" rx="4"/><path d="M12 11a4 4 0 1 0 0 6m10-6a4 4 0 1 0 0 6"/>'};
const svg=name=>`<svg viewBox="0 0 28 28" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]}</svg>`;
const time=value=>`${Math.floor((value||0)/60)}:${String(Math.floor((value||0)%60)).padStart(2,'0')}`;

export function createDuoPlayer(){
 const top=document.createElement('section');top.className='duo-player-picture';top.setAttribute('aria-label','Sintel video');
 top.innerHTML='<video playsinline loop muted preload="metadata" poster="assets/player/poster.png" src="assets/player/trailer.mp4?v=4"></video><div class="player-topbar"><span class="player-wordmark">DUO<span> CINEMA</span></span><span>9:41 &nbsp; ▰</span></div><div class="player-caption">SINTEL</div><button class="player-start" aria-label="Play Sintel trailer">'+svg('play')+'</button>';
 const bottom=document.createElement('section');bottom.className='duo-player-controls';bottom.setAttribute('aria-label','Video player controls');
 bottom.innerHTML=`<div class="player-title-row"><span class="player-n">D</span><div><strong>Sintel</strong><small>Blender Open Movie · Official teaser</small></div><button class="player-lock" aria-label="Lock player controls" aria-pressed="false">${svg('lock')}</button></div><div class="player-transport"><button data-skip="-10" aria-label="Skip back 10 seconds">${svg('back')}</button><button class="player-play" aria-label="Play">${svg('play')}</button><button data-skip="10" aria-label="Skip forward 10 seconds">${svg('forward')}</button></div><div class="player-progress"><input aria-label="Playback position" type="range" min="0" max="60" step="0.1" value="0"><div><span class="player-elapsed">0:00</span><span class="player-duration">1:00</span></div></div><div class="player-extras"><button class="player-speed" aria-label="Playback speed">1×</button><button class="player-light" aria-label="Screen brightness">${svg('light')}</button><button class="player-volume" aria-label="Unmute">${svg('mute')}</button><button class="player-expand" aria-label="Fullscreen video">${svg('expand')}</button></div><a class="player-credit" href="https://durian.blender.org/sharing/" target="_blank" rel="noopener noreferrer">Sintel © Blender Foundation · CC BY 3.0 ↗</a><span class="player-home-bar"></span>`;
 const video=top.querySelector('video'),seek=bottom.querySelector('input'),play=bottom.querySelector('.player-play');let locked=false,brightness=1;
 function paint(){const playing=!video.paused;play.innerHTML=svg(playing?'pause':'play');play.setAttribute('aria-label',playing?'Pause':'Play');top.querySelector('.player-start').hidden=playing;seek.max=Number.isFinite(video.duration)?video.duration:60;seek.value=video.currentTime;seek.style.setProperty('--progress',`${100*video.currentTime/(video.duration||60)}%`);bottom.querySelector('.player-elapsed').textContent=time(video.currentTime);bottom.querySelector('.player-duration').textContent=time(Number.isFinite(video.duration)?video.duration:60);}
 async function start(){if(locked)return;try{await video.play();}catch{top.querySelector('.player-start').setAttribute('aria-label','Retry video playback');}paint();}
 async function toggle(){if(locked)return;if(video.paused)await start();else video.pause();paint();}
 play.addEventListener('click',toggle);top.querySelector('.player-start').addEventListener('click',toggle);
 for(const type of ['play','pause','timeupdate','loadedmetadata','ended'])video.addEventListener(type,paint);
 bottom.querySelectorAll('[data-skip]').forEach(button=>button.addEventListener('click',()=>{video.currentTime=Math.max(0,Math.min(video.duration||60,video.currentTime+Number(button.dataset.skip)));}));
 seek.addEventListener('input',()=>{video.currentTime=Number(seek.value);paint();});
 bottom.querySelector('.player-volume').addEventListener('click',event=>{video.muted=!video.muted;event.currentTarget.innerHTML=svg(video.muted?'mute':'volume');event.currentTarget.setAttribute('aria-label',video.muted?'Unmute':'Mute');});
 bottom.querySelector('.player-speed').addEventListener('click',event=>{const rates=[1,1.25,1.5,2,.75];video.playbackRate=rates[(rates.indexOf(video.playbackRate)+1)%rates.length];event.currentTarget.textContent=`${video.playbackRate}×`;});
 bottom.querySelector('.player-light').addEventListener('click',()=>{brightness=brightness===1?.7:brightness===.7?.4:1;video.style.filter=`brightness(${brightness})`;});
 bottom.querySelector('.player-expand').addEventListener('click',async()=>{try{if(video.requestFullscreen)await video.requestFullscreen();else if(video.webkitEnterFullscreen)video.webkitEnterFullscreen();}catch{}});
 bottom.querySelector('.player-lock').addEventListener('click',event=>{locked=!locked;event.currentTarget.setAttribute('aria-pressed',String(locked));event.currentTarget.setAttribute('aria-label',locked?'Unlock player controls':'Lock player controls');bottom.querySelectorAll('.player-transport button,.player-extras button,input').forEach(item=>item.disabled=locked);});
 return {top,bottom,video,start,pause:()=>video.pause(),getState:()=>({paused:video.paused,time:Math.round(video.currentTime),duration:Math.round(video.duration||0),muted:video.muted,locked,playbackRate:video.playbackRate,brightness})};
}
